const API = "/api";
const ADMIN_TOKEN_KEY = "prime_admin_token";
let adminToken = null;
let services = [];
let mediaItems = [];
let portfolioItems = [];
let projects = [];
let leads = [];
let advertisements = [];
let approvedReviews = [];
let websiteDemos = [];
let leadNotifications = [];
let leadNotificationTimer = null;
const pageState = { services: 1, portfolio: 1, media: 1, projects: 1, leads: 1 };
const PAGE_SIZE = 8;

const byId = (id) => document.getElementById(id);
const escapeHTML = (value) => String(value ?? "").replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]);
const dateLabel = (value) => value ? new Date(value).toLocaleDateString(undefined, { month: "short", day: "numeric" }) : "—";
const amount = (value, currency = "INR") => `${escapeHTML(currency)} ${Number(value || 0).toLocaleString("en-IN", { maximumFractionDigits: 2 })}`;

async function apiRequest(path, options = {}) {
  const headers = { ...(options.body instanceof FormData ? {} : { "Content-Type": "application/json" }), ...(options.headers || {}) };
  if (adminToken) headers.Authorization = `Bearer ${adminToken}`;
  const response = await fetch(`${API}${path}`, { ...options, headers });
  let data = {};
  try { data = await response.json(); } catch { /* empty response */ }
  if (!response.ok) {
    if ([401, 403].includes(response.status) && adminToken) expireSession(data.error || "Your admin session is no longer valid. Please sign in again.");
    throw new Error(data.details || data.error || data.message || "Request failed. Please try again.");
  }
  return data;
}

function showNotice(id, message, type = "success") {
  const node = byId(id);
  if (!node) return;
  node.textContent = message;
  node.className = `notice ${type}`;
  node.hidden = false;
  if (type === "success") setTimeout(() => { if (node.textContent === message) node.hidden = true; }, 4500);
}

function expireSession(message) {
  if (!adminToken) return;
  adminToken = null;
  try { localStorage.removeItem(ADMIN_TOKEN_KEY); } catch { /* storage unavailable */ }
  byId("dashboardSection").hidden = true;
  byId("loginSection").hidden = false;
  if (message) showNotice("loginMessage", message, "error");
}

async function validateSession() {
  try {
    adminToken = localStorage.getItem(ADMIN_TOKEN_KEY);
    if (!adminToken) return false;
    const response = await apiRequest("/me");
    if (response.user?.role !== "admin") throw new Error("This account does not have administrator access.");
    return true;
  } catch {
    adminToken = null;
    localStorage.removeItem(ADMIN_TOKEN_KEY);
    return false;
  }
}

function navigateTo(section) {
  const valid = ["overview", "services", "portfolio", "media", "reviews", "demos", "ads", "projects", "leads", "appearance", "settings"];
  const selected = valid.includes(section) ? section : "overview";
  document.querySelectorAll("[data-view]").forEach((view) => view.classList.toggle("active", view.dataset.view === selected));
  document.querySelectorAll("[data-section]").forEach((link) => link.classList.toggle("active", link.dataset.section === selected));
  byId("sectionTitle").textContent = ({ overview: "Overview", services: "Services", portfolio: "Portfolio", media: "Media gallery", reviews: "Reviews & Ratings", demos: "Demo Management", ads: "Ads Management", projects: "Projects", leads: "Leads", appearance: "Website Appearance", settings: "Website settings" })[selected];
  byId("sectionEyebrow").textContent = selected === "overview" ? "WORKSPACE" : "MANAGE CONTENT";
  history.replaceState(null, "", `#${selected}`);
}

async function showDashboard() {
  byId("loginSection").hidden = true;
  byId("dashboardSection").hidden = false;
  navigateTo(location.hash.slice(1));
  await Promise.allSettled([loadDashboard(), loadServices(), loadMedia(), loadPortfolio(), loadProjects(), loadLeads(), loadBrand(), loadTheme(), loadAdvertisements(), loadAdPlacements(), loadApprovedReviews(),loadDemos(),loadLeadNotifications()]);if(!leadNotificationTimer)leadNotificationTimer=window.setInterval(loadLeadNotifications,30000);
}

function pager(containerId, page, pageCount, onChange) {
  const container = byId(containerId);
  if (!container) return;
  if (pageCount <= 1) { container.innerHTML = ""; return; }
  container.innerHTML = `<button type="button" data-page="${page - 1}" ${page <= 1 ? "disabled" : ""}>Previous</button><span>Page ${page} of ${pageCount}</span><button type="button" data-page="${page + 1}" ${page >= pageCount ? "disabled" : ""}>Next</button>`;
  container.querySelectorAll("button[data-page]").forEach((button) => button.addEventListener("click", () => onChange(Number(button.dataset.page))));
}

function pageItems(items, page, size = PAGE_SIZE) {
  const count = Math.max(1, Math.ceil(items.length / size));
  const safePage = Math.min(Math.max(page, 1), count);
  return { items: items.slice((safePage - 1) * size, safePage * size), page: safePage, count };
}

async function loadDashboard() {
  byId("analyticsChart").innerHTML = '<p class="empty-state">Loading live analytics…</p>';
  try {
    const data = await apiRequest("/admin/dashboard");
    byId("statVisitors").textContent = Number(data.visitors ?? 0).toLocaleString();
    byId("statToday").textContent = `Today: ${Number(data.today_visitors ?? 0).toLocaleString()}`;
    byId("statServices").textContent = Number(data.services ?? 0).toLocaleString();
    byId("statProjects").textContent = Number(data.projects ?? 0).toLocaleString();
    byId("statLeads").textContent = Number(data.leads ?? 0).toLocaleString();
    byId("statGallery").textContent = Number(data.gallery_images ?? 0).toLocaleString();
    byId("statPageViews").textContent = Number(data.page_views ?? 0).toLocaleString();
    renderAnalytics(data.analytics || []);
    renderRecent("recentProjects", data.recent_projects || [], "No projects recorded yet.", (item) => `${escapeHTML(item.title)}<small>${escapeHTML(item.customer_name || "Unassigned customer")} · ${escapeHTML(item.status)}</small>`);
    renderRecent("recentLeads", data.recent_leads || [], "No leads received yet.", (item) => `${escapeHTML(item.name)}<small>${escapeHTML(item.service_name || "General enquiry")} · ${escapeHTML(item.status)}</small>`);
  } catch (error) {
    byId("analyticsChart").innerHTML = `<p class="empty-state">${escapeHTML(error.message)}</p>`;
    showNotice("globalMessage", error.message, "error");
  }
}

function renderAnalytics(rows) {
  const host = byId("analyticsChart");
  if (!rows.length) { host.innerHTML = '<p class="empty-state">No analytics events have been recorded in the last 14 days.</p>'; return; }
  const byDate = new Map(rows.map((row) => [String(row.date).slice(0, 10), row]));
  const max = Math.max(1, ...rows.map((row) => Math.max(Number(row.events), Number(row.visitors))));
  const days = [];
  for (let offset = 13; offset >= 0; offset--) {
    const day = new Date(); day.setHours(12, 0, 0, 0); day.setDate(day.getDate() - offset);
    const key = day.toISOString().slice(0, 10);
    const row = byDate.get(key) || { events: 0, visitors: 0 };
    days.push(`<div class="chart-day" title="${key}: ${row.visitors} visitors, ${row.events} events"><div class="chart-bars"><i class="chart-bar" style="height:${Math.max(0, Number(row.visitors) / max * 100)}%"></i><i class="chart-bar events" style="height:${Math.max(0, Number(row.events) / max * 100)}%"></i></div><small>${day.toLocaleDateString(undefined, { month: "numeric", day: "numeric" })}</small></div>`);
  }
  host.innerHTML = days.join("");
}

function renderRecent(id, items, empty, format) {
  const host = byId(id);
  host.innerHTML = items.length ? items.map((item) => `<div class="recent-row"><div>${format(item)}</div><time>${dateLabel(item.created_at)}</time></div>`).join("") : `<p class="empty-state">${empty}</p>`;
}

async function loadServices() {
  const host = byId("servicesTable"); host.innerHTML = '<p class="empty-state">Loading services…</p>';
  try { const data = await apiRequest("/admin/services"); services = data.services || []; populateImageSelects(); renderServices(); }
  catch (error) { host.innerHTML = `<p class="empty-state">${escapeHTML(error.message)}</p>`; }
}

function renderServices() {
  const term = byId("serviceSearch").value.trim().toLowerCase();
  const filter = byId("serviceFilter").value;
  const sort = byId("serviceSortBy").value;
  const list = services.filter((item) => `${item.name} ${item.category} ${item.description || ""}`.toLowerCase().includes(term) && (filter === "all" || (filter === "published") === item.is_active));
  list.sort((a, b) => sort === "name" ? a.name.localeCompare(b.name) : sort === "price" ? Number(a.price) - Number(b.price) : Number(a.sort_order) - Number(b.sort_order));
  const page = pageItems(list, pageState.services); pageState.services = page.page;
  byId("servicesTable").innerHTML = page.items.length ? `<table class="admin-table"><thead><tr><th>Service</th><th>Price</th><th>Order</th><th>Status</th><th>Actions</th></tr></thead><tbody>${page.items.map((item) => `<tr><td>${escapeHTML(item.name)}<small class="muted">${escapeHTML(item.category)}</small></td><td>${amount(item.price,item.currency)}<small class="muted">Maint. ${amount(item.maintenance_price,item.currency)}</small></td><td>${item.sort_order}</td><td><span class="pill ${item.is_active ? "" : "hidden"}">${item.is_active ? "Published" : "Hidden"}</span></td><td><div class="row-actions"><button data-edit-service="${item.id}">Edit</button><button data-toggle-service="${item.id}">${item.is_active ? "Hide" : "Publish"}</button><button data-order-service="${item.id}" data-step="-1">↑</button><button data-order-service="${item.id}" data-step="1">↓</button><button data-delete-service="${item.id}">Delete</button></div></td></tr>`).join("")}</tbody></table>` : '<p class="empty-state">No services match these filters.</p>';
  pager("servicesPager", page.page, page.count, (value) => { pageState.services = value; renderServices(); });
  byId("servicesTable").querySelectorAll("[data-edit-service]").forEach((button) => button.addEventListener("click", () => editService(button.dataset.editService)));
  byId("servicesTable").querySelectorAll("[data-toggle-service]").forEach((button) => button.addEventListener("click", () => toggleService(button.dataset.toggleService)));
  byId("servicesTable").querySelectorAll("[data-order-service]").forEach((button) => button.addEventListener("click", () => moveService(button.dataset.orderService, Number(button.dataset.step))));
  byId("servicesTable").querySelectorAll("[data-delete-service]").forEach((button) => button.addEventListener("click", () => deleteService(button.dataset.deleteService)));
}

function populateImageSelects() {
  const options = `<option value="">No image</option>${mediaItems.map((item) => `<option value="${escapeHTML(item.image_url)}">${escapeHTML(item.title)}</option>`).join("")}`;
  for (const id of ["serviceImage", "portfolioImage"]) { const select = byId(id); const oldValue = select.value; select.innerHTML = options; if ([...select.options].some((option) => option.value === oldValue)) select.value = oldValue; }
  updateServicePreview();
}

function retainImageOption(selectId, imageUrl, label) {
  if (!imageUrl) return;
  const select = byId(selectId);
  if (![...select.options].some((option) => option.value === imageUrl)) {
    const option = document.createElement("option");
    option.value = imageUrl;
    option.textContent = label || "Current image";
    select.append(option);
  }
}

function servicePayload() {
  return { name: byId("serviceName").value.trim(), slug: byId("serviceSlug").value.trim().toLowerCase(), category: byId("serviceCategory").value.trim(), description: byId("serviceDescription").value.trim(), price: Number(byId("servicePrice").value), currency: byId("serviceCurrency").value.trim().toUpperCase(), price_label: byId("servicePriceLabel").value.trim(), maintenance_price: Number(byId("serviceMaintenance").value || 0), billing_label: byId("serviceBilling").value.trim(), features: byId("serviceFeatures").value.split(/\r?\n/).map((value) => value.trim()).filter(Boolean), image_url: byId("serviceImage").value || null, is_active: byId("serviceActive").checked, sort_order: Number(byId("serviceSort").value || 0), sale_enabled: byId("serviceSaleEnabled").checked, discount_type: byId("serviceDiscountType").value, discount_value: Number(byId("serviceDiscountValue").value || 0), offer_badge_text: byId("serviceOfferBadge").value.trim(), sale_start_date: byId("serviceSaleStart").value || null, sale_end_date: byId("serviceSaleEnd").value || null };
}

function updateServicePreview() {
  const item = servicePayload();
  const validDiscount = item.discount_type === "percentage" ? item.discount_value >= 0 && item.discount_value < 100 : item.discount_value >= 0 && item.discount_value < item.price;
  const inDates = (!item.sale_start_date || item.sale_start_date <= new Date().toISOString().slice(0,10)) && (!item.sale_end_date || item.sale_end_date >= new Date().toISOString().slice(0,10));
  const saving = item.sale_enabled && item.price > 0 && validDiscount && inDates ? Math.round((item.discount_type === "percentage" ? item.price * item.discount_value / 100 : item.discount_value) * 100) / 100 : 0;
  const salePrice = Math.max(0, Math.round((item.price - saving) * 100) / 100);
  byId("serviceSalePrice").textContent = amount(salePrice,item.currency);
  byId("serviceSavings").textContent = amount(saving,item.currency);
  const image = item.image_url ? `<img src="${escapeHTML(item.image_url)}" alt="">` : "P";
  byId("servicePreview").innerHTML = `<div class="preview-art">${image}${saving ? `<b class="sale-badge">${escapeHTML(item.offer_badge_text || (item.discount_type === "percentage" ? `${item.discount_value}% OFF` : "SALE"))}</b>` : ""}</div><div><span>${escapeHTML(item.category || "CATEGORY")}</span><h3>${escapeHTML(item.name || "Service name")}</h3><p>${escapeHTML(item.description || "Description preview")}</p><strong>${amount(saving ? salePrice : item.price,item.currency)}${saving ? ` <del>${amount(item.price,item.currency)}</del>` : ""}</strong>${saving ? `<small class="sale-savings">You Save ${amount(saving,item.currency)}</small>` : ""}<small class="muted">Maintenance ${amount(item.maintenance_price,item.currency)} / ${escapeHTML(item.billing_label || "one-time")}</small></div>`;
}

function resetServiceForm() { byId("serviceForm").reset(); byId("serviceId").value = ""; byId("serviceActive").checked = true; byId("serviceSort").value = "0"; byId("serviceCurrency").value = "INR"; byId("serviceFormTitle").textContent = "Create service"; byId("serviceCancel").hidden = true; updateServicePreview(); }
function editService(id) {
  const item = services.find((service) => String(service.id) === String(id)); if (!item) return;
  retainImageOption("serviceImage", item.image_url, "Current service image");
  byId("serviceId").value = item.id; byId("serviceName").value = item.name; byId("serviceSlug").value = item.slug || ""; byId("serviceCategory").value = item.category || ""; byId("serviceSort").value = item.sort_order; byId("serviceDescription").value = item.description || ""; byId("servicePrice").value = item.price; byId("serviceCurrency").value = item.currency || "INR"; byId("servicePriceLabel").value = item.price_label || ""; byId("serviceMaintenance").value = item.maintenance_price; byId("serviceBilling").value = item.billing_label || "one-time"; byId("serviceFeatures").value = (item.features || []).join("\n"); byId("serviceActive").checked = item.is_active; byId("serviceImage").value = item.image_url || ""; byId("serviceSaleEnabled").checked = Boolean(item.sale_enabled); byId("serviceDiscountType").value = item.discount_type || "percentage"; byId("serviceDiscountValue").value = item.discount_value || 0; byId("serviceOfferBadge").value = item.offer_badge_text || ""; byId("serviceSaleStart").value = item.sale_start_date ? String(item.sale_start_date).slice(0,10) : ""; byId("serviceSaleEnd").value = item.sale_end_date ? String(item.sale_end_date).slice(0,10) : ""; byId("serviceFormTitle").textContent = "Edit service"; byId("serviceCancel").hidden = false; updateServicePreview(); byId("serviceForm").scrollIntoView({ behavior: "smooth", block: "start" });
}

async function saveService(event) {
  event.preventDefault(); const id = byId("serviceId").value; const payload = servicePayload();
  try { await apiRequest(id ? `/admin/services/${id}` : "/admin/services", { method: id ? "PUT" : "POST", body: JSON.stringify(payload) }); showNotice("serviceMessage", "Service saved."); resetServiceForm(); await Promise.all([loadServices(), loadDashboard()]); }
  catch (error) { showNotice("serviceMessage", error.message, "error"); }
}
async function toggleService(id) { const item = services.find((service) => String(service.id) === String(id)); if (!item) return; try { await apiRequest(`/admin/services/${id}`, { method: "PUT", body: JSON.stringify({ ...item, is_active: !item.is_active }) }); await Promise.all([loadServices(), loadDashboard()]); } catch (error) { showNotice("globalMessage", error.message, "error"); } }
async function moveService(id, step) { const sorted = [...services].sort((a,b)=>Number(a.sort_order)-Number(b.sort_order)); const index = sorted.findIndex((item)=>String(item.id)===String(id)); const other=sorted[index+step]; if (!other) return; try { await Promise.all([apiRequest(`/admin/services/${sorted[index].id}`,{method:"PUT",body:JSON.stringify({...sorted[index],sort_order:Number(other.sort_order)} )}),apiRequest(`/admin/services/${other.id}`,{method:"PUT",body:JSON.stringify({...other,sort_order:Number(sorted[index].sort_order)})})]); await loadServices(); } catch(error){showNotice("globalMessage",error.message,"error");} }
async function deleteService(id) { const item=services.find((entry)=>String(entry.id)===String(id)); if(!item||!confirm(`Delete “${item.name}”? Services linked to projects or leads will be protected; you can hide this service instead.`))return; try { await apiRequest(`/admin/services/${id}`,{method:"DELETE"}); await Promise.all([loadServices(),loadDashboard()]); } catch(error){showNotice("globalMessage",error.message,"error");} }

async function loadMedia() {
  const host=byId("mediaGrid"); host.innerHTML='<p class="empty-state">Loading gallery…</p>';
  try { const q=encodeURIComponent(byId("mediaSearch")?.value.trim()||"");const category=encodeURIComponent(byId("mediaCategoryFilter")?.value||"");const data=await apiRequest(`/admin/media?page=${pageState.media}&limit=12&q=${q}&category=${category}`); mediaItems=data.media||[];renderMedia(data);populateImageSelects();populateDemoMedia(); }
  catch(error){host.innerHTML=`<p class="empty-state">${escapeHTML(error.message)}</p>`;}
}
function renderMedia(data) {
  const host=byId("mediaGrid");
  host.innerHTML=mediaItems.length?mediaItems.map((item)=>`<article class="media-card" data-media-id="${item.id}"><img src="${escapeHTML(item.image_url)}" alt="${escapeHTML(item.alt_text)}" loading="lazy"><div class="media-card-body"><input data-media-field="title" value="${escapeHTML(item.title)}" aria-label="Image title"><input data-media-field="alt_text" value="${escapeHTML(item.alt_text)}" aria-label="Alt text"><input data-media-field="category" value="${escapeHTML(item.category)}" aria-label="Category"><input data-media-field="caption" value="${escapeHTML(item.caption||"")}" aria-label="Caption"><label class="check-row"><input data-media-field="is_published" type="checkbox" ${item.is_published?"checked":""}> Public gallery</label><div class="media-meta"><span>${(item.file_size/1024).toFixed(0)} KB · ${item.mime_type.replace("image/","")}</span><span>${item.is_published?"Published":"Private"}</span></div><div class="row-actions"><button data-save-media="${item.id}">Save details</button><button data-delete-media="${item.id}">Delete</button><button data-select-image="${escapeHTML(item.image_url)}" data-title="${escapeHTML(item.title)}">Use in form</button></div></div></article>`).join(""):'<p class="empty-state">No images found. Upload an image to start the gallery.</p>';
  pager("mediaPager",data.page,Math.ceil(data.total/data.limit),(value)=>{pageState.media=value;loadMedia();});
  const filter=byId("mediaCategoryFilter");const selected=filter.value;const categories=[...new Set(mediaItems.map((item)=>item.category))];filter.innerHTML='<option value="">All categories</option>'+categories.map((category)=>`<option value="${escapeHTML(category)}">${escapeHTML(category)}</option>`).join("");if(categories.includes(selected))filter.value=selected;
  host.querySelectorAll("[data-save-media]").forEach((button)=>button.addEventListener("click",()=>saveMedia(button)));
  host.querySelectorAll("[data-delete-media]").forEach((button)=>button.addEventListener("click",()=>deleteMedia(button.dataset.deleteMedia)));
  host.querySelectorAll("[data-select-image]").forEach((button)=>button.addEventListener("click",()=>{const service=byId("serviceImage");const portfolio=byId("portfolioImage");const select=location.hash==="#portfolio"?portfolio:service;if(![...select.options].some((option)=>option.value===button.dataset.selectImage)){const option=document.createElement("option");option.value=button.dataset.selectImage;option.textContent=button.dataset.title;select.append(option);}select.value=button.dataset.selectImage;navigateTo(location.hash.slice(1)==="portfolio"?"portfolio":"services");updateServicePreview();}));
}
async function saveMedia(button){const card=button.closest(".media-card");const payload={};card.querySelectorAll("[data-media-field]").forEach((field)=>{payload[field.dataset.mediaField]=field.type==="checkbox"?field.checked:field.value;});try{await apiRequest(`/admin/media/${button.dataset.saveMedia}`,{method:"PUT",body:JSON.stringify(payload)});showNotice("mediaMessage","Image details saved.");await loadMedia();}catch(error){showNotice("mediaMessage",error.message,"error");}}
async function deleteMedia(id){const item=mediaItems.find((entry)=>String(entry.id)===String(id));if(!item||!confirm(`Delete image “${item.title}”? Images in use by the site cannot be deleted.`))return;try{await apiRequest(`/admin/media/${id}`,{method:"DELETE"});await Promise.all([loadMedia(),loadDashboard()]);}catch(error){showNotice("globalMessage",error.message,"error");}}
async function uploadMedia(event){event.preventDefault();const file=byId("mediaFile").files[0];if(!file)return;if(file.size>5*1024*1024){showNotice("mediaMessage","Choose an image no larger than 5 MB.","error");return;}const reader=new FileReader();reader.onerror=()=>showNotice("mediaMessage","The selected image could not be read.","error");reader.onload=async()=>{try{await apiRequest("/admin/media",{method:"POST",body:JSON.stringify({title:byId("mediaTitle").value.trim(),alt_text:byId("mediaAlt").value.trim(),category:byId("mediaCategory").value.trim(),caption:byId("mediaCaption").value.trim(),is_published:byId("mediaPublished").checked,mime_type:file.type,data_url:reader.result})});showNotice("mediaMessage","Image uploaded and stored.");byId("mediaUploadForm").reset();byId("mediaFileLabel").textContent="Select from your computer";pageState.media=1;await Promise.all([loadMedia(),loadDashboard()]);}catch(error){showNotice("mediaMessage",error.message,"error");}};reader.readAsDataURL(file);}

async function loadPortfolio(){byId("portfolioList").innerHTML='<p class="empty-state">Loading portfolio…</p>';try{const data=await apiRequest("/admin/portfolio");portfolioItems=data.portfolio||[];renderPortfolio();}catch(error){byId("portfolioList").innerHTML=`<p class="empty-state">${escapeHTML(error.message)}</p>`;}}
function renderPortfolio(){const term=byId("portfolioSearch").value.trim().toLowerCase();const list=portfolioItems.filter((item)=>`${item.title} ${item.category||""}`.toLowerCase().includes(term));const page=pageItems(list,pageState.portfolio);pageState.portfolio=page.page;byId("portfolioList").innerHTML=page.items.length?`<table class="admin-table"><thead><tr><th>Project</th><th>Publication</th><th>Actions</th></tr></thead><tbody>${page.items.map((item)=>`<tr><td>${escapeHTML(item.title)}<small class="muted">${escapeHTML(item.category||"Uncategorised")}</small></td><td><span class="pill ${item.is_published?"":"hidden"}">${item.is_published?"Published":"Draft"}</span></td><td><div class="row-actions"><button data-edit-portfolio="${item.id}">Edit</button><button data-toggle-portfolio="${item.id}">${item.is_published?"Unpublish":"Publish"}</button><button data-delete-portfolio="${item.id}">Delete</button></div></td></tr>`).join("")}</tbody></table>`:'<p class="empty-state">No portfolio entries match this search.</p>';pager("portfolioPager",page.page,page.count,(value)=>{pageState.portfolio=value;renderPortfolio();});byId("portfolioList").querySelectorAll("[data-edit-portfolio]").forEach((button)=>button.addEventListener("click",()=>editPortfolio(button.dataset.editPortfolio)));byId("portfolioList").querySelectorAll("[data-toggle-portfolio]").forEach((button)=>button.addEventListener("click",()=>updatePortfolio(button.dataset.togglePortfolio,{is_published:!portfolioItems.find((x)=>String(x.id)===button.dataset.togglePortfolio).is_published})));byId("portfolioList").querySelectorAll("[data-delete-portfolio]").forEach((button)=>button.addEventListener("click",()=>deletePortfolio(button.dataset.deletePortfolio)));}
function portfolioPayload(){return{title:byId("portfolioTitle").value.trim(),slug:byId("portfolioSlug").value.trim(),category:byId("portfolioCategory").value.trim(),description:byId("portfolioDescription").value.trim(),project_url:byId("portfolioUrl").value.trim()||null,technologies:byId("portfolioTechnologies").value.split(/\r?\n/).map((x)=>x.trim()).filter(Boolean),image_url:byId("portfolioImage").value||null,sort_order:Number(byId("portfolioSort").value||0),is_published:byId("portfolioPublished").checked};}
function resetPortfolio(){byId("portfolioForm").reset();byId("portfolioId").value="";byId("portfolioFormTitle").textContent="Add portfolio project";byId("portfolioCancel").hidden=true;}
function editPortfolio(id){const item=portfolioItems.find((x)=>String(x.id)===String(id));if(!item)return;retainImageOption("portfolioImage",item.image_url,"Current portfolio image");byId("portfolioId").value=item.id;byId("portfolioTitle").value=item.title;byId("portfolioSlug").value=item.slug||"";byId("portfolioCategory").value=item.category||"";byId("portfolioDescription").value=item.description||"";byId("portfolioUrl").value=item.project_url||"";byId("portfolioTechnologies").value=(item.technologies||[]).join("\n");byId("portfolioImage").value=item.image_url||"";byId("portfolioSort").value=item.sort_order;byId("portfolioPublished").checked=item.is_published;byId("portfolioFormTitle").textContent="Edit portfolio project";byId("portfolioCancel").hidden=false;byId("portfolioForm").scrollIntoView({behavior:"smooth"});}
async function savePortfolio(event){event.preventDefault();const id=byId("portfolioId").value;try{await apiRequest(id?`/admin/portfolio/${id}`:"/admin/portfolio",{method:id?"PUT":"POST",body:JSON.stringify(portfolioPayload())});showNotice("portfolioMessage","Portfolio project saved.");resetPortfolio();await Promise.all([loadPortfolio(),loadDashboard()]);}catch(error){showNotice("portfolioMessage",error.message,"error");}}
async function updatePortfolio(id,patch){const item=portfolioItems.find((x)=>String(x.id)===String(id));try{await apiRequest(`/admin/portfolio/${id}`,{method:"PUT",body:JSON.stringify({...item,...patch})});await Promise.all([loadPortfolio(),loadDashboard()]);}catch(error){showNotice("globalMessage",error.message,"error");}}
async function deletePortfolio(id){const item=portfolioItems.find((x)=>String(x.id)===String(id));if(!item||!confirm(`Delete portfolio project “${item.title}”?`))return;try{await apiRequest(`/admin/portfolio/${id}`,{method:"DELETE"});await Promise.all([loadPortfolio(),loadDashboard()]);}catch(error){showNotice("globalMessage",error.message,"error");}}

async function loadProjects(){byId("projectsTable").innerHTML='<p class="empty-state">Loading projects…</p>';try{const data=await apiRequest("/admin/projects");projects=data.projects||[];const notice=byId("projectNotificationStatus"),count=Number(data.unread_count||0);if(notice){notice.textContent=count?`${count} unread project request/update notification${count===1?"":"s"}. Open a project to review it and mark it read.`:"No unread project notifications.";notice.hidden=false;}renderProjects();}catch(error){byId("projectsTable").innerHTML=`<p class="empty-state">${escapeHTML(error.message)}</p>`;const notice=byId("projectNotificationStatus");if(notice){notice.textContent="Project notification status is unavailable.";notice.hidden=false;notice.classList.add("error");}}}function projectStatusLabel(value){return ({pending:"Pending review",accepted:"Accepted",in_progress:"Approved / In progress",delayed:"Delayed",rejected:"Rejected",completed:"Completed",on_hold:"On hold (legacy)",cancelled:"Cancelled (legacy)"})[value]||value;}
function projectStatusOptions(current){const choices={pending:["pending","accepted","rejected"],accepted:["accepted","in_progress","delayed","rejected"],in_progress:["in_progress","delayed","completed"],delayed:["delayed","in_progress","completed","rejected"],rejected:["rejected"],completed:["completed"],on_hold:["on_hold","accepted","in_progress","delayed","rejected","completed","cancelled"],cancelled:["cancelled"]};return choices[current]||[current];}
function projectMilestoneText(items){return (items||[]).map(x=>`${x.title} | ${x.status} | ${x.target_date||""}`).join("\n");}
function projectDateValue(value){return value?String(value).slice(0,10):"";}
function renderProjects(){const term=byId("projectSearch").value.toLowerCase().trim();const status=byId("projectFilter").value;const sort=byId("projectSort").value;const statuses=[...new Set(projects.map(p=>p.status))];const filter=byId("projectFilter"),old=filter.value;filter.innerHTML='<option value="all">All statuses</option>'+statuses.map(s=>`<option value="${escapeHTML(s)}">${escapeHTML(projectStatusLabel(s))}</option>`).join("");if(statuses.includes(old))filter.value=old;const list=projects.filter(p=>`${p.title} ${p.customer_name||""} ${p.customer_email||""} ${p.service_name||""} ${p.project_reference||""}`.toLowerCase().includes(term)&&(status==="all"||p.status===status));list.sort((a,b)=>sort==="oldest"?new Date(a.created_at)-new Date(b.created_at):sort==="title"?a.title.localeCompare(b.title):new Date(b.created_at)-new Date(a.created_at));const page=pageItems(list,pageState.projects);pageState.projects=page.page;const rows=page.items.map(p=>{const options=projectStatusOptions(p.status),stages=["request_received","requirements_confirmed","design_in_progress","development_in_progress","testing_revisions","customer_review","completed"];return `<tr><td><strong>${escapeHTML(p.title)}</strong><small>${escapeHTML(p.project_reference||`#${p.id}`)} · ${escapeHTML(p.project_type||"Project")}</small></td><td>${escapeHTML(p.customer_name||p.customer_email||"Unassigned")}<small>${escapeHTML(p.customer_email||"")}</small></td><td>${escapeHTML(p.service_name||"—")}</td><td><span class="pill">${escapeHTML(projectStatusLabel(p.status))}</span>${Number(p.unread_updates)>0?`<small class="config-warning">${Number(p.unread_updates)} unread update${Number(p.unread_updates)===1?"":"s"}</small>`:""}</td><td><span class="pill">${escapeHTML(p.whatsapp_status||"not configured")}</span>${p.whatsapp_status==="failed"?`<button type="button" class="admin-quiet" data-project-retry-wa="${p.id}">Retry WhatsApp</button>`:""}${p.whatsapp_error?`<small class="muted">${escapeHTML(p.whatsapp_error)}</small>`:""}</td><td>${dateLabel(p.created_at)}</td></tr><tr><td colspan="6"><details class="project-admin-details" data-project-details="${p.id}"><summary>Manage ${escapeHTML(p.project_reference||`project #${p.id}`)}${p.latest_update?` · latest: ${escapeHTML(p.latest_update)}`:""}</summary><div class="project-admin-controls"><div class="form-pair"><label>Status<select data-project-status>${options.map(v=>`<option value="${v}" ${p.status===v?"selected":""}>${escapeHTML(projectStatusLabel(v))}</option>`).join("")}</select></label><label>Stage<select data-project-stage>${stages.map(v=>`<option value="${v}" ${(p.stage||"request_received")===v?"selected":""}>${escapeHTML(v.replaceAll("_"," "))}</option>`).join("")}</select></label></div><div class="form-pair"><label>Progress (%)<input data-project-progress type="number" min="0" max="100" step="1" value="${Number(p.progress_percent||0)}"></label><label>Estimated start<input data-project-start type="date" value="${projectDateValue(p.estimated_start_date)}"></label></div><div class="form-pair"><label>Estimated completion<input data-project-deadline type="date" value="${projectDateValue(p.deadline)}"></label><label>Reason for delay<textarea data-project-delay maxlength="3000" rows="2">${escapeHTML(p.delay_reason||"")}</textarea></label></div><label>Rejection reason<textarea data-project-rejection maxlength="3000" rows="2">${escapeHTML(p.decision_reason||"")}</textarea></label><label>Customer update / progress note<textarea data-project-note maxlength="5000" rows="2" placeholder="Share a clear project update"></textarea></label><label>Milestones (one per line: title | pending/in_progress/completed/cancelled | optional YYYY-MM-DD)<textarea data-project-milestones rows="4" placeholder="Requirements confirmed | pending | 2026-10-30">${escapeHTML(projectMilestoneText(p.milestones))}</textarea></label><div class="form-actions"><button type="button" class="admin-primary" data-project-save="${p.id}">Save project update</button><button type="button" class="admin-quiet" data-project-mark-read="${p.id}" ${Number(p.unread_updates)>0?"":"hidden"}>Mark updates read</button></div><label class="project-file-picker">Attach project image or PDF (max 8 MiB)<input type="file" accept="image/jpeg,image/png,image/webp,application/pdf" data-project-file="${p.id}"></label><label class="check-row"><input type="checkbox" data-project-file-visible="${p.id}"> Make this file visible to the customer</label><div data-project-activity="${p.id}" class="project-activity-list"><p class="muted">Open project details to load the activity history and files.</p></div></div></details></td></tr>`;}).join("");byId("projectsTable").innerHTML=rows?`<table class="admin-table"><thead><tr><th>Project</th><th>Customer</th><th>Service</th><th>Status</th><th>WhatsApp</th><th>Created</th></tr></thead><tbody>${rows}</tbody></table>`:'<p class="empty-state">No projects match these filters.</p>';pager("projectsPager",page.page,page.count,v=>{pageState.projects=v;renderProjects();});byId("projectsTable").querySelectorAll("[data-project-save]").forEach(button=>button.addEventListener("click",()=>saveProjectWorkflow(button.dataset.projectSave,button.closest("details"))));byId("projectsTable").querySelectorAll("[data-project-mark-read]").forEach(button=>button.addEventListener("click",async()=>{button.disabled=true;try{await apiRequest(`/admin/projects/${button.dataset.projectMarkRead}/read`,{method:"POST",body:JSON.stringify({})});await loadProjects();}catch(error){showNotice("globalMessage",error.message,"error");}finally{button.disabled=false;}}));byId("projectsTable").querySelectorAll("[data-project-details]").forEach(details=>details.addEventListener("toggle",()=>{if(details.open)loadProjectActivity(details.dataset.projectDetails);}));byId("projectsTable").querySelectorAll("[data-project-file]").forEach(input=>input.addEventListener("change",()=>uploadProjectFile(input.dataset.projectFile,input)));byId("projectsTable").querySelectorAll("[data-project-retry-wa]").forEach(button=>button.addEventListener("click",async()=>{button.disabled=true;try{const result=await apiRequest(`/admin/projects/${button.dataset.projectRetryWa}/whatsapp/retry`,{method:"POST",body:JSON.stringify({})});showNotice("globalMessage",result.message||`WhatsApp status: ${result.status}`,"success");await loadProjects();}catch(error){showNotice("globalMessage",error.message,"error");}finally{button.disabled=false;}}));}
async function saveProjectWorkflow(id,panel){const button=panel.querySelector("[data-project-save]");button.disabled=true;try{const milestoneText=panel.querySelector("[data-project-milestones]").value;const milestones=milestoneText.split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map(line=>{const [title,status="pending",target_date=""]=line.split("|").map(x=>x.trim());return {title,status,target_date:target_date||null};});const payload={status:panel.querySelector("[data-project-status]").value,stage:panel.querySelector("[data-project-stage]").value,progress_percent:Number(panel.querySelector("[data-project-progress]").value),estimated_start_date:panel.querySelector("[data-project-start]").value||null,deadline:panel.querySelector("[data-project-deadline]").value||null,delay_reason:panel.querySelector("[data-project-delay]").value.trim(),decision_reason:panel.querySelector("[data-project-rejection]").value.trim(),update_note:panel.querySelector("[data-project-note]").value.trim(),milestones,request_key:button.dataset.requestKey||(button.dataset.requestKey=crypto.randomUUID())};await apiRequest(`/admin/projects/${id}`,{method:"PUT",body:JSON.stringify(payload)});showNotice("globalMessage","Project update saved. A customer in-app notification is recorded when the project is linked to a customer.");await Promise.all([loadProjects(),loadDashboard()]);}catch(error){showNotice("globalMessage",error.message,"error");}finally{button.disabled=false;}}
async function loadProjectActivity(id){const host=byId("projectsTable").querySelector(`[data-project-activity="${id}"]`);if(!host||host.dataset.loaded==="true")return;host.dataset.loaded="true";try{const data=await apiRequest(`/customer/projects/${id}`);const form=host.closest("details");const project=data.project||{};form.querySelector("[data-project-status]").value=project.status;form.querySelector("[data-project-stage]").value=project.stage||"request_received";form.querySelector("[data-project-progress]").value=project.progress_percent||0;form.querySelector("[data-project-start]").value=projectDateValue(project.estimated_start_date);form.querySelector("[data-project-deadline]").value=projectDateValue(project.deadline);form.querySelector("[data-project-delay]").value=project.delay_reason||"";form.querySelector("[data-project-rejection]").value=project.decision_reason||"";form.querySelector("[data-project-milestones]").value=projectMilestoneText(data.milestones);const events=data.activity||[],files=data.files||[],messages=data.messages||[];host.innerHTML=`<h4>Project history</h4>${events.length?`<ol>${events.map(e=>`<li><strong>${escapeHTML(e.title)}</strong>${e.note?`<p>${escapeHTML(e.note)}</p>`:""}<time>${dateLabel(e.created_at)}</time></li>`).join("")}`:'<p class="muted">No updates have been recorded yet.</p>'}<h4>Project files</h4>${files.length?files.map(f=>`<button type="button" class="admin-quiet" data-project-download="${f.id}" data-project-id="${id}">${escapeHTML(f.original_name)} · ${(Number(f.file_size)/1024).toFixed(0)} KB${f.is_customer_visible?" · Customer visible":" · Admin only"}</button>`).join(""):'<p class="muted">No project files attached.</p>'}<h4>Messages</h4>${messages.length?messages.map(m=>`<p><strong>${escapeHTML(m.sender_name||"Team")}</strong> · ${dateLabel(m.created_at)}<br>${escapeHTML(m.message)}</p>`).join(""):'<p class="muted">No project messages yet.</p>'}`;host.querySelectorAll("[data-project-download]").forEach(button=>button.addEventListener("click",()=>downloadProjectFile(button.dataset.projectId,button.dataset.projectDownload)));}catch(error){host.dataset.loaded="false";host.textContent=error.message;}}
async function downloadProjectFile(projectId,fileId){try{const response=await fetch(`${API}/customer/projects/${projectId}/files/${fileId}`,{headers:{Authorization:`Bearer ${adminToken}`}});if(!response.ok)throw new Error("Unable to open this project file.");const url=URL.createObjectURL(await response.blob()),a=document.createElement("a");a.href=url;a.download="project-file";a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(error){showNotice("globalMessage",error.message,"error");}}
async function uploadProjectFile(projectId,input){const file=input.files?.[0];if(!file)return;if(!["image/jpeg","image/png","image/webp","application/pdf"].includes(file.type)||file.size<=0||file.size>8*1024*1024){showNotice("globalMessage","Choose a JPG, PNG, WebP, or PDF file no larger than 8 MiB.","error");input.value="";return;}const reader=new FileReader();reader.onerror=()=>showNotice("globalMessage","Unable to read the selected project file.","error");reader.onload=async()=>{input.disabled=true;try{const visible=byId("projectsTable").querySelector(`[data-project-file-visible="${projectId}"]`).checked;await apiRequest(`/admin/projects/${projectId}/files`,{method:"POST",body:JSON.stringify({name:file.name,data_url:reader.result,is_customer_visible:visible})});showNotice("globalMessage","Project file uploaded securely.");await loadProjects();}catch(error){showNotice("globalMessage",error.message,"error");}finally{input.disabled=false;}};reader.readAsDataURL(file);}

async function loadLeadNotifications(){try{const data=await apiRequest("/admin/lead-notifications");leadNotifications=data.notifications||[];const count=Number(data.unread_count||0),badge=byId("leadUnreadBadge"),host=byId("leadNotifications");badge.textContent=String(count);badge.hidden=count===0;host.replaceChildren();const unread=leadNotifications.filter(n=>!n.read_at);if(!unread.length){host.innerHTML='<p class="muted">No unread lead notifications.</p>';return;}for(const n of unread){const item=document.createElement("article");item.className="lead-notification-card";const copy=document.createElement("div"),title=document.createElement("strong");title.textContent="New lead "+(n.lead_reference||"#"+n.lead_id);copy.append(title);for(const [label,value] of [["Name",n.name],["Phone",n.phone],["Email",n.email],["Service",n.service_name||"General enquiry"],["Message",n.message],["Source",n.source||"Website"],["Status / received",`${n.status||"new"} / ${dateLabel(n.created_at)}`]]){if(!value)continue;const line=document.createElement("p");line.textContent=label+": "+value;copy.append(line);}const button=document.createElement("button");button.type="button";button.className="admin-quiet";button.textContent="Open lead and mark read";button.addEventListener("click",async()=>{button.disabled=true;try{await apiRequest("/admin/lead-notifications/"+n.id+"/read",{method:"POST",body:JSON.stringify({})});await loadLeadNotifications();navigateTo("leads");await loadLeads();[...document.querySelectorAll("[data-lead-row]")].find(row=>row.dataset.leadRow===String(n.lead_id))?.scrollIntoView({behavior:"smooth",block:"center"});}catch(e){showNotice("globalMessage",e.message,"error");}finally{button.disabled=false;}});item.append(copy,button);host.append(item);}}catch(e){const host=byId("leadNotifications");if(host)host.textContent="Lead notification status is unavailable.";}}
async function loadLeads(){byId("leadsTable").innerHTML='<p class="empty-state">Loading leads…</p>';try{const data=await apiRequest("/admin/leads");leads=data.leads||[];renderLeads();}catch(error){byId("leadsTable").innerHTML=`<p class="empty-state">${escapeHTML(error.message)}</p>`;}}
function renderLeads(){const term=byId("leadSearch").value.toLowerCase().trim();const status=byId("leadFilter").value;const sort=byId("leadSort").value;const statuses=[...new Set(leads.map((l)=>l.status))];const filter=byId("leadFilter");const old=filter.value;filter.innerHTML='<option value="all">All statuses</option>'+statuses.map((s)=>`<option value="${escapeHTML(s)}">${escapeHTML(s)}</option>`).join("");if(statuses.includes(old))filter.value=old;const list=leads.filter((l)=>`${l.name} ${l.email||""} ${l.phone||""} ${l.service_name||""} ${l.lead_reference||""}`.toLowerCase().includes(term)&&(status==="all"||l.status===status));list.sort((a,b)=>sort==="oldest"?new Date(a.created_at)-new Date(b.created_at):sort==="name"?a.name.localeCompare(b.name):new Date(b.created_at)-new Date(a.created_at));const page=pageItems(list,pageState.leads);pageState.leads=page.page;byId("leadsTable").innerHTML=page.items.length?`<table class="admin-table"><thead><tr><th>Lead / Contact</th><th>Service / Price</th><th>Request</th><th>Status</th><th>WhatsApp</th><th>Received</th></tr></thead><tbody>${page.items.map((l)=>`<tr data-lead-row="${l.id}"><td><strong>${escapeHTML(l.lead_reference||`#${l.id}`)}</strong><small>${escapeHTML(l.name)} · ${escapeHTML(l.phone||"")}</small><small class="muted">${escapeHTML(l.email||"")}</small></td><td>${escapeHTML(l.service_name||"General enquiry")}<small class="muted">${l.sale_price_snapshot!=null?`${amount(l.sale_price_snapshot,l.currency_snapshot)}${Number(l.sale_price_snapshot)!==Number(l.original_price_snapshot)?` · Original ${amount(l.original_price_snapshot,l.currency_snapshot)}`:""}`:"Quote requested"}</small></td><td>${escapeHTML(l.message||"—")}<details class="lead-attachments-details"><summary>Details and attachments (${(l.attachments||[]).length})</summary><p>Country code: ${escapeHTML(l.country_code||"Legacy lead")} · Consent: ${l.consent_at?dateLabel(l.consent_at):"Legacy record"}</p><div>${(l.attachments||[]).map((a)=>`<button type="button" class="admin-quiet" data-view-lead-file="${l.id}" data-attachment-id="${a.id}" data-filename="${escapeHTML(a.original_name)}">View ${escapeHTML(a.original_name)} · ${(Number(a.file_size)/1024).toFixed(0)} KB</button>`).join("")||"No attachments"}</div></details></td><td><select data-lead-status="${l.id}">${["new","contacted","qualified","converted","closed"].map((s)=>`<option value="${s}" ${l.status===s?"selected":""}>${s}</option>`).join("")}</select></td><td><span class="pill">${escapeHTML(l.whatsapp_notification_status||"not configured")}</span>${["failed","not_configured"].includes(l.whatsapp_notification_status)||((l.attachments||[]).some((a)=>a.whatsapp_status==="failed"))?`<button type="button" class="admin-quiet" data-retry-whatsapp="${l.id}">Retry</button>`:""}${l.whatsapp_error?`<small class="muted">${escapeHTML(l.whatsapp_error)}</small>`:""}</td><td>${dateLabel(l.created_at)}</td></tr>`).join("")}</tbody></table>`:'<p class="empty-state">No leads match these filters.</p>';pager("leadsPager",page.page,page.count,(v)=>{pageState.leads=v;renderLeads();});byId("leadsTable").querySelectorAll("[data-lead-status]").forEach((select)=>select.addEventListener("change",async()=>{try{await apiRequest(`/admin/leads/${select.dataset.leadStatus}`,{method:"PUT",body:JSON.stringify({status:select.value})});await Promise.all([loadLeads(),loadDashboard()]);}catch(error){showNotice("globalMessage",error.message,"error");}}));byId("leadsTable").querySelectorAll("[data-retry-whatsapp]").forEach((button)=>button.addEventListener("click",async()=>{button.disabled=true;try{const result=await apiRequest(`/admin/leads/${button.dataset.retryWhatsapp}/whatsapp/retry`,{method:"POST",body:JSON.stringify({})});showNotice("globalMessage",`WhatsApp notification status: ${result.status}${result.error?`. ${result.error}`:""}`,result.success?"success":"error");await loadLeads();}catch(error){showNotice("globalMessage",error.message,"error");}finally{button.disabled=false;}}));byId("leadsTable").querySelectorAll("[data-view-lead-file]").forEach((button)=>button.addEventListener("click",async()=>{const preview=window.open("about:blank","_blank");try{const response=await fetch(`${API}/admin/leads/${button.dataset.viewLeadFile}/attachments/${button.dataset.attachmentId}`,{headers:{Authorization:`Bearer ${adminToken}`}});if(!response.ok)throw new Error("Unable to open this private attachment.");const url=URL.createObjectURL(await response.blob());if(preview)preview.location=url;else{const anchor=document.createElement("a");anchor.href=url;anchor.download=button.dataset.filename;anchor.click();}window.setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(error){preview?.close();showNotice("globalMessage",error.message,"error");}}));}

async function loadAdminLogoPublic(){try{const response=await fetch(`${API}/public/brand`,{cache:"no-store"});if(!response.ok)return;const {brand={}}=await response.json();for(const [id,fallbackId,nameId] of [["adminBrandLogo","adminWordmarkFallback","adminBrandName"],["adminLoginBrandLogo","adminLoginFallback","adminLoginBrandName"]]){const image=byId(id),fallback=byId(fallbackId),name=byId(nameId);if(name){name.querySelector("strong").textContent=(brand.short_name||brand.company_name||"Prime").toUpperCase();name.querySelector("small").textContent=brand.company_name||"WEB AGENCY";}const url=brand.admin_logo_url||brand.logo_url||"";if(image&&fallback){if(url){image.src=`${url}${url.includes("?")?"&":"?"}v=${Date.now()}`;image.alt=brand.logo_alt_text||`${brand.company_name||"Prime Web Agency"} logo`;image.hidden=false;fallback.hidden=true;image.onerror=()=>{image.hidden=true;fallback.hidden=false;};}else{image.hidden=true;fallback.hidden=false;}}}}catch(error){console.warn("Unable to load admin brand logo:",error.message);}}async function loadBrand(){try{const data=await apiRequest("/admin/brand");const b=data.brand||{};for(const [id,value] of Object.entries({brandCompanyName:b.company_name,brandShortName:b.short_name,brandDomain:b.domain_name,brandTagline:b.tagline,brandLogo:b.logo_url,brandFavicon:b.favicon_url,brandWebsiteLogo:b.brand_logos?.website,brandAdminLogo:b.brand_logos?.admin,brandCustomerLogo:b.brand_logos?.customer,brandLogoAlt:b.brand_logos?.alt_text,brandPrimary:isHexColor(b.primary_color)?b.primary_color:"#7c5cff",brandSecondary:isHexColor(b.secondary_color)?b.secondary_color:"#00d4ff",brandHeroTitle:b.hero_title,brandHeroDescription:b.hero_description,brandHeroImage:b.hero_image_url,brandAboutTitle:b.about_title,brandAboutDescription:b.about_description,brandFooter:b.footer_text,brandEmail:b.email,brandPhone:b.phone,brandWhatsapp:b.whatsapp,brandCurrency:b.currency||"INR",brandAddress:b.address,brandSeoTitle:b.seo_title,brandSeoImage:b.seo_image,brandSeoDescription:b.seo_description,brandTheme:b.theme_default||"system",socialInstagram:b.social_links?.instagram,socialFacebook:b.social_links?.facebook,socialLinkedin:b.social_links?.linkedin,socialYoutube:b.social_links?.youtube}))if(byId(id))byId(id).value=value||"";const preview=byId("brandLogoPreview");if(preview&&b.logo_url){preview.src=b.logo_url;preview.hidden=false;}const adminLogo=byId("adminBrandLogo");if(adminLogo){const logo=b.admin_logo_url||"";adminLogo.hidden=!logo;if(logo){adminLogo.src=logo+`?v=${Date.now()}`;adminLogo.onerror=()=>{adminLogo.hidden=true;byId("adminWordmarkFallback").hidden=false;};byId("adminWordmarkFallback").hidden=true;}else byId("adminWordmarkFallback").hidden=false;}const adminName=byId("adminBrandName");if(adminName){adminName.querySelector("strong").textContent=(b.short_name||b.company_name||"Prime").toUpperCase();adminName.querySelector("small").textContent=b.company_name||"WEB AGENCY";}const visibility=b.section_visibility||{};document.querySelectorAll("[data-section-visible]").forEach((input)=>input.checked=visibility[input.dataset.sectionVisible]!==false);byId("brandSectionOrder").value=(b.section_order||["services","automation","about","portfolio","gallery","process","contact"]).join(",");await loadWhatsAppConfig();}catch(error){showNotice("globalMessage",error.message,"error");}}
async function loadWhatsAppConfig(){try{const s=await apiRequest("/admin/whatsapp/status");const fill={whatsappEnabled:s.enabled,whatsappNotifyLeads:s.notify_new_leads,whatsappNotifyServices:s.notify_service_inquiries,whatsappNotifyProjects:s.notify_project_requests,whatsappNotifyAttachments:s.notify_attachments,whatsappCustomerConfirmation:s.customer_confirmation,whatsappScheduleEnabled:s.schedule_enabled,whatsappTimezone:s.timezone||"Asia/Kolkata",whatsappStartTime:s.start_time||"09:00",whatsappEndTime:s.end_time||"18:00",whatsappTemplateName:s.notification_template_name||"prime_new_lead",whatsappTemplateLanguage:s.notification_template_language||"en",whatsappCustomerTemplate:s.customer_template_name||"prime_request_received",whatsappCustomerTemplateLanguage:s.customer_template_language||"en"};for(const[id,value]of Object.entries(fill)){const n=byId(id);if(n){if(n.type==="checkbox")n.checked=Boolean(value);else n.value=value;}}let phone=String(s.recipient_phone||s.effective_recipient||"").replace(/\D/g,"");let code="+91";for(const option of [...byId("whatsappCountryCode").options].sort((a,b)=>b.value.length-a.value.length)){if(phone.startsWith(option.value.slice(1))){code=option.value;phone=phone.slice(option.value.length-1);break;}}byId("whatsappCountryCode").value=code;byId("whatsappRecipientPhone").value=phone;document.querySelectorAll("[data-wa-day]").forEach(n=>n.checked=(s.allowed_days||[]).includes(Number(n.dataset.waDay)));const host=byId("whatsappConfigStatus");host.textContent=s.message;host.className=`notice ${s.configured?"success":"error"}`;byId("whatsappLastSuccess").textContent=s.last_success_at?new Date(s.last_success_at).toLocaleString():"Never";byId("whatsappConnectionState").textContent=s.connection_status+(s.connection_checked_at?` · ${new Date(s.connection_checked_at).toLocaleString()}`:"");byId("whatsappQueueSummary").textContent=Object.entries(s.queue||{}).map(([k,v])=>`${k}: ${v}`).join(" · ")||"Empty";const error=byId("whatsappLastError");error.textContent=s.last_error||"";error.hidden=!s.last_error;}catch(error){const host=byId("whatsappConfigStatus");if(host){host.textContent=error.message;host.className="notice error";}}}
async function saveWhatsAppSettings(event){event.preventDefault();const button=event.submitter||event.currentTarget.querySelector("button[type=submit]");button.disabled=true;const p={enabled:byId("whatsappEnabled").checked,notify_new_leads:byId("whatsappNotifyLeads").checked,notify_service_inquiries:byId("whatsappNotifyServices").checked,notify_project_requests:byId("whatsappNotifyProjects").checked,notify_attachments:byId("whatsappNotifyAttachments").checked,customer_confirmation:byId("whatsappCustomerConfirmation").checked,schedule_enabled:byId("whatsappScheduleEnabled").checked,allowed_days:[...document.querySelectorAll("[data-wa-day]:checked")].map(n=>Number(n.dataset.waDay)),start_time:byId("whatsappStartTime").value,end_time:byId("whatsappEndTime").value,timezone:byId("whatsappTimezone").value.trim(),recipient_country_code:byId("whatsappCountryCode").value,recipient_local_phone:byId("whatsappRecipientPhone").value.trim(),notification_template_name:byId("whatsappTemplateName").value.trim(),notification_template_language:byId("whatsappTemplateLanguage").value.trim(),customer_template_name:byId("whatsappCustomerTemplate").value.trim(),customer_template_language:byId("whatsappCustomerTemplateLanguage").value.trim()};try{await apiRequest("/admin/whatsapp/settings",{method:"PUT",body:JSON.stringify(p)});showNotice("whatsappSettingsMessage","WhatsApp settings saved. Pending notifications will re-check the current settings.");await loadWhatsAppConfig();}catch(error){showNotice("whatsappSettingsMessage",error.message,"error");}finally{button.disabled=false;}}
async function testWhatsAppConnection(){const button=byId("whatsappTestConnection");button.disabled=true;try{const r=await apiRequest("/admin/whatsapp/test-connection",{method:"POST",body:JSON.stringify({})});showNotice("whatsappSettingsMessage",`${r.message}${r.verified_name?` Business: ${r.verified_name}.`:""}${r.display_phone_number?` Provider number: ${r.display_phone_number}.`:""}`);await loadWhatsAppConfig();}catch(error){showNotice("whatsappSettingsMessage",error.message,"error");await loadWhatsAppConfig();}finally{button.disabled=false;}}
