  ["serviceSaleEnabled","serviceDiscountType"].forEach((id)=>byId(id).addEventListener("change",updateServicePreview));
  ["serviceSearch","serviceFilter","serviceSortBy"].forEach((id)=>byId(id).addEventListener(id==="serviceSearch"?"input":"change",()=>{pageState.services=1;renderServices();}));
  byId("mediaUploadForm").addEventListener("submit",uploadMedia);byId("mediaFile").addEventListener("change",()=>{const file=byId("mediaFile").files[0];byId("mediaFileLabel").textContent=file?`${file.name} · ${(file.size/1024/1024).toFixed(2)} MB`:"Select from your computer";if(file&&!byId("mediaTitle").value)byId("mediaTitle").value=file.name.replace(/\.[^.]+$/,"");});
  byId("mediaSearch").addEventListener("input",()=>{pageState.media=1;loadMedia();});byId("mediaCategoryFilter").addEventListener("change",()=>{pageState.media=1;loadMedia();});
  byId("portfolioForm").addEventListener("submit",savePortfolio);byId("portfolioCancel").addEventListener("click",resetPortfolio);byId("portfolioSearch").addEventListener("input",()=>{pageState.portfolio=1;renderPortfolio();});byId("portfolioTitle").addEventListener("input",()=>{if(!byId("portfolioId").value&&!byId("portfolioSlug").dataset.edited)byId("portfolioSlug").value=byId("portfolioTitle").value.toLowerCase().trim().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");});byId("portfolioSlug").addEventListener("input",()=>byId("portfolioSlug").dataset.edited="true");
  ["projectSearch","projectFilter","projectSort"].forEach((id)=>byId(id).addEventListener(id==="projectSearch"?"input":"change",()=>{pageState.projects=1;renderProjects();}));["leadSearch","leadFilter","leadSort"].forEach((id)=>byId(id).addEventListener(id==="leadSearch"?"input":"change",()=>{pageState.leads=1;renderLeads();}));
  byId("brandForm").addEventListener("submit",saveBrand);
  byId("themeForm").addEventListener("submit",saveThemeDraft);byId("publishThemeBtn").addEventListener("click",publishTheme);byId("resetThemeBtn").addEventListener("click",resetThemeDraft);
  byId("reviewForm").addEventListener("submit",saveReview);byId("newDemoBtn").addEventListener("click",()=>{resetDemo();byId("demoForm").hidden=false;});byId("demoCancel").addEventListener("click",resetDemo);byId("reviewFilter").addEventListener("change",renderReviews);byId("reviewRatingFilter").addEventListener("change",renderReviews);byId("demoForm").addEventListener("submit",saveDemo);byId("demoPreviewBtn").addEventListener("click",previewDemo);byId("demoSearch").addEventListener("input",renderDemos);byId("demoFilter").addEventListener("change",renderDemos);byId("reviewCancel").addEventListener("click",resetReview);
  byId("newAdBtn").addEventListener("click",()=>{resetAd();byId("adForm").hidden=false;byId("adName").focus();});byId("cancelAdBtn").addEventListener("click",resetAd);byId("adForm").addEventListener("submit",saveAd);["adName","adHeadline","adDescription","adCtaText","adPlacement","adAnimation","adSpeed","adTextColor","adBgColor","adAlign"].forEach(id=>byId(id).addEventListener("input",updateAdPreview));byId("adFile").addEventListener("change",()=>{const input=byId("adFile");if(input.dataset.previewUrl)URL.revokeObjectURL(input.dataset.previewUrl);input.dataset.previewUrl=input.files[0]?URL.createObjectURL(input.files[0]):"";byId("adMediaPreview").dataset.mime=input.files[0]?.type||"";updateAdPreview();});byId("adSearch").addEventListener("input",renderAds);byId("adFilter").addEventListener("change",renderAds);
  byId("whatsappSettingsForm").addEventListener("submit",saveWhatsAppSettings);byId("whatsappTestConnection").addEventListener("click",testWhatsAppConnection);byId("whatsappTestMessage").addEventListener("click",sendWhatsAppTestMessage);
  byId("browseBrandLogo").addEventListener("click",()=>byId("brandLogoFile").click());byId("uploadBrandLogo").addEventListener("click",uploadBrandLogo);byId("brandLogoFile").addEventListener("change",()=>selectBrandLogo(byId("brandLogoFile").files[0]));
  const logoDrop=byId("logoUploadDrop");logoDrop.addEventListener("click",(event)=>{if(!event.target.closest("button"))byId("brandLogoFile").click();});logoDrop.addEventListener("keydown",(event)=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();byId("brandLogoFile").click();}});logoDrop.addEventListener("dragover",(event)=>{event.preventDefault();logoDrop.classList.add("drag-over");});logoDrop.addEventListener("dragleave",()=>logoDrop.classList.remove("drag-over"));logoDrop.addEventListener("drop",(event)=>{event.preventDefault();logoDrop.classList.remove("drag-over");selectBrandLogo(event.dataTransfer.files[0]);});
  const themeSelect=document.querySelector("[data-theme-selector]");const saved=localStorage.getItem("prime-web-agency-theme")||"system";themeSelect.value=saved;themeSelect.addEventListener("change",()=>applyTheme(themeSelect.value));
  window.addEventListener("hashchange",()=>navigateTo(location.hash.slice(1)));
