function adState(a){if(!a.is_enabled)return "Disabled";if(a.status!=="published")return "Draft";const now=Date.now();if(a.start_at&&Date.parse(a.start_at)>now)return "Scheduled";if(a.end_at&&Date.parse(a.end_at)<=now)return "Expired";return "Active";}
