async function uploadAdFile(file,kind){const max=file.type.startsWith("video/")?8*1024*1024:5*1024*1024;if(file.size>max)throw new Error(`Choose a file no larger than ${max/1024/1024} MB.`);const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error("Unable to read selected file."));reader.onload=()=>resolve(reader.result);reader.readAsDataURL(file);});return apiRequest("/admin/advertisements/upload",{method:"POST",body:JSON.stringify({data_url:data,kind})});}
